 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("home",0);getWindow().setStatusBarColor(0xff15203b);getWindow().setNavigationBarColor(0xff20223e);load();home();}
 void load(){apps.clear();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);apps.addAll(getPackageManager().queryIntentActivities(q,0));apps.removeIf(a->a.activityInfo.packageName.equals(getPackageName()));Collections.sort(apps,new ResolveInfo.DisplayNameComparator(getPackageManager()));}
 String key(ResolveInfo a){return new ComponentName(a.activityInfo.packageName,a.activityInfo.name).flattenToString();}
 boolean hidden(ResolveInfo a){return prefs.getStringSet("hidden",new HashSet<>()).contains(key(a));}
