 void auth(Runnable next){KeyguardManager k=getSystemService(KeyguardManager.class);if(!k.isDeviceSecure()){new AlertDialog.Builder(this).setTitle("Screen lock required").setMessage("Set a device PIN, pattern or password first. Launcher editing stays locked until a device screen lock is configured.").setPositiveButton("Security settings",(d,n)->open(new Intent(Settings.ACTION_SECURITY_SETTINGS))).setNegativeButton("Cancel",null).show();return;}Intent i=k.createConfirmDeviceCredentialIntent("Unlock Island Home","Confirm device screen lock to edit launcher");if(i==null){Toast.makeText(this,"Device authentication unavailable",1).show();return;}afterUnlock=next;startActivityForResult(i,AUTH);}
 void shell(){backdrop=new FrameLayout(this);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff173759,0xff514477,0xffb06b83});backdrop.setBackground(gradient);String wall=prefs.getString("wall","");if(!wall.isEmpty())try{ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setImageURI(Uri.parse(wall));backdrop.addView(im,new FrameLayout.LayoutParams(-1,-1));View shade=new View(this);shade.setBackgroundColor(0x33000000);backdrop.addView(shade,new FrameLayout.LayoutParams(-1,-1));}catch(Exception e){}root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(10));backdrop.addView(root,new FrameLayout.LayoutParams(-1,-1));setContentView(backdrop);View.OnLongClickListener edit=v->{auth(()->settings());return true;};root.setOnLongClickListener(edit);backdrop.setOnLongClickListener(edit);columns=getResources().getConfiguration().screenWidthDp>=600?6:4;width=getResources().getDisplayMetrics().widthPixels-dp(24);}
 void home(){inLibrary=false;shell();ArrayList<ResolveInfo> list=visible();int rows=getResources().getConfiguration().screenHeightDp<600?2:3;int per=rows*columns;int total=Math.max(1,(list.size()+per-1)/per);page=Math.max(0,Math.min(page,total-1));
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout content=new LinearLayout(this);content.setOrientation(1);scroll.addView(content);content.setOnLongClickListener(v->{auth(()->settings());return true;});
 LinearLayout cards=new LinearLayout(this);cards.setPadding(0,dp(6),0,dp(12));content.addView(cards);calendarCard(cards);statusCard(cards);
 GridLayout grid=new GridLayout(this);grid.setColumnCount(columns);content.addView(grid);for(int i=page*per;i<Math.min(list.size(),(page+1)*per);i++){GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=width/columns;p.height=dp(92);grid.addView(tile(list.get(i),true,54),p);}grid.setMinimumHeight(dp(rows*92));grid.setOnLongClickListener(v->{auth(()->settings());return true;});
 View.OnTouchListener swipe=(v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN)downX=e.getX();if(e.getAction()==MotionEvent.ACTION_UP){float delta=e.getX()-downX;if(Math.abs(delta)>dp(65)){if(delta<0){if(page<total-1){page++;home();}else library();}else if(page>0){page--;home();}return true;}}return false;};scroll.setOnTouchListener(swipe);grid.setOnTouchListener(swipe);
 LinearLayout navigation=new LinearLayout(this);TextView prev=txt("‹",26),dots=txt("",13),next=txt("›",26);StringBuilder dotsText=new StringBuilder();for(int i=0;i<total;i++)dotsText.append(i==page?"● ":"○ ");dots.setText(dotsText);navigation.addView(prev,new LinearLayout.LayoutParams(dp(48),dp(32)));navigation.addView(dots,new LinearLayout.LayoutParams(0,dp(32),1));navigation.addView(next,new LinearLayout.LayoutParams(dp(48),dp(32)));root.addView(navigation);prev.setOnClickListener(v->{if(page>0){page--;home();}});next.setOnClickListener(v->{if(page<total-1){page++;home();}else library();});
 TextView search=txt("Search · App Library",14);search.setBackground(rounded(0x44ffffff,22));root.addView(search,new LinearLayout.LayoutParams(-1,dp(34)));search.setOnClickListener(v->library());LinearLayout dock=new LinearLayout(this);dock.setGravity(Gravity.CENTER);dock.setPadding(dp(4),dp(8),dp(4),dp(8));dock.setBackground(rounded(0x77ffffff,28));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(82));p.topMargin=dp(9);root.addView(dock,p);
 for(int i=0;i<4;i++){final int slot=i;ResolveInfo a=find(prefs.getString("dock"+i,""));if(a!=null&&hidden(a))a=null;View item=a==null?txt("+",26):tile(a,false,54);dock.addView(item,new LinearLayout.LayoutParams(0,-1,1));if(a==null)item.setOnClickListener(v->auth(()->pickDock(slot)));item.setOnLongClickListener(v->{auth(()->pickDock(slot));return true;});}}
 LinearLayout card(LinearLayout row){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setGravity(Gravity.CENTER);c.setPadding(dp(8),dp(8),dp(8),dp(8));c.setBackground(rounded(0xccf6f4fc,24));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(142),1);p.setMargins(dp(4),0,dp(4),0);row.addView(c,p);c.setOnLongClickListener(v->{auth(()->settings());return true;});return c;}
 void calendarCard(LinearLayout row){LinearLayout c=card(row);TextClock day=new TextClock(this);day.setFormat12Hour("EEEE");day.setFormat24Hour("EEEE");day.setTextColor(0xffd34356);day.setTextSize(15);day.setGravity(Gravity.CENTER);c.addView(day);TextClock date=new TextClock(this);date.setFormat12Hour("d");date.setFormat24Hour("d");date.setTextColor(0xff202030);date.setTextSize(46);date.setGravity(Gravity.CENTER);c.addView(date);TextClock month=new TextClock(this);month.setFormat12Hour("MMMM yyyy");month.setFormat24Hour("MMMM yyyy");month.setTextColor(0xff555566);month.setGravity(Gravity.CENTER);c.addView(month);c.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_APP_CALENDAR);open(i);});}
 void statusCard(LinearLayout row){LinearLayout c=card(row);TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(26);clock.setTextColor(0xff202030);clock.setGravity(Gravity.CENTER);c.addView(clock);Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=b==null?-1:b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1);int scale=b==null?100:b.getIntExtra(BatteryManager.EXTRA_SCALE,100);int pct=level<0||scale<=0?-1:Math.round(100f*level/scale);TextView battery=txt(pct<0?"Battery unavailable":"Battery  "+pct+"%",15);battery.setTextColor(0xff167c52);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(42));c.addView(battery,p);TextView hint=txt("Hold wallpaper to edit",10);hint.setTextColor(0xff666677);c.addView(hint);}
 View tile(ResolveInfo a,boolean label,int size){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER);box.setPadding(dp(2),dp(3),dp(2),dp(3));ImageView icon=new ImageView(this);icon.setImageBitmap(iconBitmap(a));box.addView(icon,new LinearLayout.LayoutParams(dp(size),dp(size)));if(label){TextView t=txt(a.loadLabel(getPackageManager()).toString(),11);t.setMaxLines(1);t.setEllipsize(android.text.TextUtils.TruncateAt.END);t.setShadowLayer(3,0,1,0xff000000);box.addView(t,new LinearLayout.LayoutParams(-1,dp(22)));}box.setOnClickListener(v->launch(a));box.setOnLongClickListener(v->{auth(()->appOptions(a));return true;});return box;}
 Bitmap iconBitmap(ResolveInfo a){int s=dp(64);Bitmap b=Bitmap.createBitmap(s,s,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);int h=key(a).hashCode();int base=Color.HSVToColor(new float[]{(h&0x7fffffff)%360,0.48f,0.88f});p.setShader(new LinearGradient(0,0,s,s,new int[]{base,Color.rgb(Math.max(0,Color.red(base)-40),Math.max(0,Color.green(base)-40),Math.max(0,Color.blue(base)-40))},null,Shader.TileMode.CLAMP));canvas.drawRoundRect(0,0,s,s,s*.24f,s*.24f,p);Drawable d=a.loadIcon(getPackageManager());int inset=(int)(s*.13f);d.setBounds(inset,inset,s-inset,s-inset);d.draw(canvas);return b;}
 ResolveInfo find(String k){for(ResolveInfo a:apps)if(key(a).equals(k))return a;return null;}
 void launch(ResolveInfo a){if(hidden(a))return;open(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName(a.activityInfo.packageName,a.activityInfo.name)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED));}
 void open(Intent i){try{startActivity(i);}catch(Exception e){Toast.makeText(this,"No compatible app or action available",1).show();}}
 void appOptions(ResolveInfo a){new AlertDialog.Builder(this).setTitle(a.loadLabel(getPackageManager())).setItems(new String[]{"Hide everywhere in this launcher","App information"},(d,n)->{if(n==1){open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.activityInfo.packageName)));return;}Set<String> h=new HashSet<>(prefs.getStringSet("hidden",new HashSet<>()));h.add(key(a));SharedPreferences.Editor edit=prefs.edit().putStringSet("hidden",h);for(int i=0;i<4;i++)if(prefs.getString("dock"+i,"").equals(key(a)))edit.remove("dock"+i);edit.apply();home();}).show();}
 void pickDock(int slot){ArrayList<ResolveInfo> list=visible();String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=list.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Choose dock app").setItems(names,(d,n)->{prefs.edit().putString("dock"+slot,key(list.get(n))).apply();home();}).setNeutralButton("Clear",(d,n)->{prefs.edit().remove("dock"+slot).apply();home();}).show();}
 String category(ResolveInfo a){int n=a.activityInfo.applicationInfo.category;switch(n){case ApplicationInfo.CATEGORY_GAME:return "Games";case ApplicationInfo.CATEGORY_AUDIO:return "Music & Audio";case ApplicationInfo.CATEGORY_VIDEO:return "Video";case ApplicationInfo.CATEGORY_IMAGE:return "Photos";case ApplicationInfo.CATEGORY_SOCIAL:return "Social";case ApplicationInfo.CATEGORY_NEWS:return "News";case ApplicationInfo.CATEGORY_MAPS:return "Travel";case ApplicationInfo.CATEGORY_PRODUCTIVITY:return "Productivity";default:return "Other Apps";}}
 void library(){inLibrary=true;shell();TextView back=txt("‹ Home       App Library",22);root.addView(back,new LinearLayout.LayoutParams(-1,dp(48)));back.setOnClickListener(v->home());EditText search=new EditText(this);search.setSingleLine(true);search.setTextColor(-1);search.setHintTextColor(0xffdddddd);search.setHint("Search visible apps");root.addView(search);ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout results=new LinearLayout(this);results.setOrientation(1);sc.addView(results);
 Runnable render=()->{results.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);TreeMap<String,ArrayList<ResolveInfo>> groups=new TreeMap<>();for(ResolveInfo a:visible()){if(!a.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT).contains(q))continue;String cat=category(a);if(!groups.containsKey(cat))groups.put(cat,new ArrayList<>());groups.get(cat).add(a);}for(String cat:groups.keySet()){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(8),dp(8),dp(8),dp(8));card.setBackground(rounded(0x55ffffff,25));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(7),0,dp(7));results.addView(card,cp);TextView heading=txt(cat,17);card.addView(heading,new LinearLayout.LayoutParams(-1,dp(32)));GridLayout grid=new GridLayout(this);grid.setColumnCount(columns);card.addView(grid);for(ResolveInfo a:groups.get(cat)){GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=(width-dp(16))/columns;p.height=dp(88);grid.addView(tile(a,true,50),p);}}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(Editable e){}});render.run();}
 void hiddenManager(){ArrayList<ResolveInfo> list=new ArrayList<>();for(ResolveInfo a:apps)if(hidden(a))list.add(a);if(list.isEmpty()){Toast.makeText(this,"No hidden apps",0).show();return;}String[] labels=new String[list.size()];boolean[] selected=new boolean[list.size()];for(int i=0;i<labels.length;i++)labels[i]=list.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Select apps to unhide").setMultiChoiceItems(labels,selected,(d,n,on)->selected[n]=on).setPositiveButton("Unhide selected",(d,n)->{Set<String> h=new HashSet<>(prefs.getStringSet("hidden",new HashSet<>()));for(int i=0;i<selected.length;i++)if(selected[i])h.remove(key(list.get(i)));prefs.edit().putStringSet("hidden",h).apply();home();}).setNegativeButton("Cancel",null).show();}
 void settings(){String[] options={"Set default Home","Overlay permission","Notification / media access","Service notifications","Start Island","Stop Island","Choose wallpaper","Reset wallpaper","Island position","Manage hidden apps","System settings"};new AlertDialog.Builder(this).setTitle("Unlocked launcher settings").setItems(options,(d,n)->{switch(n){case 0:if(Build.VERSION.SDK_INT>=29){RoleManager r=getSystemService(RoleManager.class);if(r.isRoleAvailable(RoleManager.ROLE_HOME)){startActivityForResult(r.createRequestRoleIntent(RoleManager.ROLE_HOME),703);break;}}open(new Intent(Settings.ACTION_HOME_SETTINGS));break;case 1:open(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));break;case 2:open(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS));break;case 3:if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},704);break;case 4:if(!Settings.canDrawOverlays(this)){Toast.makeText(this,"Grant overlay permission first",1).show();break;}try{startForegroundService(new Intent(this,IslandService.class));}catch(Exception e){Toast.makeText(this,e.toString(),1).show();}break;case 5:stopService(new Intent(this,IslandService.class));break;case 6:startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),WALL);break;case 7:prefs.edit().remove("wall").apply();home();break;case 8:SeekBar seek=new SeekBar(this);seek.setMax(160);seek.setProgress(prefs.getInt("islandY",4));new AlertDialog.Builder(this).setTitle("Top offset (dp)").setView(seek).setPositiveButton("Save",(x,y)->{prefs.edit().putInt("islandY",seek.getProgress()).apply();if(IslandService.instance!=null)IslandService.instance.reposition();}).show();break;case 9:hiddenManager();break;case 10:open(new Intent(Settings.ACTION_SETTINGS));}}).show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==AUTH){Runnable task=afterUnlock;afterUnlock=null;if(result==RESULT_OK&&task!=null)task.run();return;}if(request==WALL&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception e){}prefs.edit().putString("wall",u.toString()).apply();home();}}
 protected void onNewIntent(Intent i){super.onNewIntent(i);afterUnlock=null;load();home();}
 public void onBackPressed(){if(inLibrary)home();else super.onBackPressed();}
 protected void onResume(){super.onResume();if(prefs!=null&&afterUnlock==null){load();if(!inLibrary)home();}}
